SELECT Имена_областей.NAME AS Obl_name, Sum_chast.Stan_name, Nz(STAN.MAZUT,0) AS x1, Sum_chast.MAZUT AS x2, [x1] - [x2] AS d_mazut, Nz(STAN.UGOL,0) AS y1, Sum_chast.UGOL AS y2, [y1] - [y2] AS d_ugol, Nz(STAN.GAZ,0) AS z1, Sum_chast.GAZ AS z2, [z1] - [z2] AS d_gaz, Nz(STAN.ISK_GAZ,0) AS m1, Sum_chast.ISK_GAZ AS m2, [m1] - [m2] AS d_isk_gaz, Nz(STAN.TORF,0) AS n1, Sum_chast.TORF AS n2, [n1] - [n2] AS d_torf, Nz(STAN.PROCH,0) AS q1, Sum_chast.PROCH AS q2, [q1] - [q2] AS d_proch, Nz(STAN.E,0) AS w1, Sum_chast.E AS w2, [w1] - [w2] AS d_E, Nz(STAN.Q,0) AS v1, Sum_chast.Q AS v2, [v1] - [v2] AS d_Q, Nz(STAN.QOTR,0) AS u1, Sum_chast.QOTR AS u2, [u1] - [u2] AS d_QOTR, STAN.Year, Nz(STAN.B,0) AS r1, Sum_chast.B AS r2, [r1] - [r2] AS d_B, Nz(STAN.PECH,0) AS s1, Sum_chast.PECH AS s2, [s1] - [s2] AS d_PECH, Nz(STAN.KUZN,0) AS a1, Sum_chast.KUZN AS a2, [a1] - [a2] AS d_KUZN, Nz(STAN.KAZAH,0) AS b1, Sum_chast.KAZAH AS b2, [b1] - [b2] AS d_KAZAH, Nz(STAN.KAN,0) AS c1, Sum_chast.KAN AS c2, [c1] - [c2] AS d_KAN, Nz(STAN.IRKUT,0) AS f1, Sum_chast.IRKUT AS f2, [f1] - [f2] AS d_IRKUT, Nz(STAN.HAK,0) AS g1, Sum_chast.HAK AS g2, [g1] - [g2] AS d_HAK, Nz(STAN.AMUR,0) AS h1, Sum_chast.AMUR AS h2, [h1] - [h2] AS d_AMUR, Nz(STAN.PRIM,0) AS k1, Sum_chast.PRIM AS k2, [k1] - [k2] AS d_PRIM, Nz(STAN.DON,0) AS d1, Sum_chast.DON AS d2, [d1] - [d2] AS d_DON, Nz(STAN.PODM,0) AS p1, Sum_chast.PODM AS p2, [p1] - [p2] AS d_PODM, Nz(STAN.URAL,0) AS ul1, Sum_chast.URAL AS ul2, [ul1] - [ul2] AS d_URAL, Nz(STAN.BASHK,0) AS ba1, Sum_chast.BASHK AS ba2, [ba1] - [ba2] AS d_BASHK, Nz(STAN.TUV,0) AS t1, Sum_chast.TUV AS t2, [t1] - [t2] AS d_TUV, Nz(STAN.BUR,0) AS bu1, Sum_chast.BUR AS bu2, [bu1] - [bu2] AS d_BUR, Nz(STAN.CHIT,0) AS ch1, Sum_chast.CHIT AS ch2, [ch1] - [ch2] AS d_CHIT, Nz(STAN.YAKUT,0) AS ya1, Sum_chast.YAKUT AS ya2, [ya1] - [ya2] AS d_YAKUT, Nz(STAN.URG,0) AS ur1, Sum_chast.URG AS ur2, [ur1] - [ur2] AS d_URG, Nz(STAN.MAG,0) AS ma1, Sum_chast.MAG AS ma2, [ma1] - [ma2] AS d_MAG, Nz(STAN.CHUKOT,0) AS cu1, Sum_chast.CHUKOT AS cu2, [cu1] - [cu2] AS d_CHUKOT, Nz(STAN.SAH,0) AS sa1, Sum_chast.SAH AS sa2, [sa1] - [sa2] AS d_SAH, Nz(STAN.KAMCH,0) AS ka1, Sum_chast.KAMCH AS ka2, [cu1] - [cu2] AS d_KAMCH
FROM (Станции2024 AS STAN INNER JOIN Сумма_частей AS Sum_chast ON STAN.NUMB1120 = Sum_chast.NUMB1120) INNER JOIN Имена_областей ON STAN.OBL = Имена_областей.OBL;
